(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+wx1, sy = y+wy1;
  const wx2 = Math.sin(sx*0.03+t*0.5)*8+Math.cos(sy*0.025-t*0.4)*6;
  const wy2 = Math.cos(sy*0.03-t*0.45)*8+Math.sin(sx*0.028+t*0.55)*6;
  const fx = sx+wx2, fy = sy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [60+Math.sin(t*0.45+1)*60,40+Math.cos(t*0.65+2)*40,0.14,2.1],
    [420+Math.cos(t*0.55+3)*70,200+Math.sin(t*0.75+1)*50,0.11,1.8],
    [200+Math.sin(t*0.25+4)*90,220+Math.cos(t*0.45+3)*60,0.09,2.4],
    [300+Math.cos(t*0.65+5)*80,30+Math.sin(t*0.35+2)*50,0.13,2.0]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS+=Math.sin(d*f*1.3-t*sp*0.8+2.5);
  }
  const n=src.length,act=aS/n,inh=iS/n,hyb=hS/n;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2
    +Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2
    +Math.sin(fx*0.08+fy*0.06-t*1.5)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.08-ang*2+t*0.9)*0.2+Math.cos(dist*0.06+ang*5-t*1.8)*0.15;
  const rd1=act-inh*0.7+bg*0.3+spiral;
  const rd2=act*inh*0.5+hyb*0.4-bg*0.2;
  const rd3=Math.sin((act+hyb)*Math.PI)*0.6-Math.cos(inh*Math.PI)*0.3;
  const reaction=Math.tanh((rd1+rd2*0.3+rd3*0.2)*2.2);
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const fine=Math.sin(fx*0.3+t*3)*Math.sin(fy*0.35-t*2.5)*0.15;
  const blend=reaction*0.65+cell*0.2+fine*0.15, v=blend*0.5+0.5;
  const pal=[
    [5,10,48],[8,45,78],[14,95,115],[32,148,142],
    [160,172,55],[195,138,45],[185,88,58],[148,48,55],
    [78,22,48],[5,10,48]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:1.0;
  const glow=Math.max(0,reaction)*0.1;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*30)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0
  ];
}
